from src.nodes.base import BaseNode
from src.runtime.lighting import get_lighting_readability_engine
import json

class Hou_Mcp_Lighting_Readability(BaseNode):
    name = "hou_mcp_lighting_readability"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("plan_json", "string", widget_type="text", default="")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("result_json", "string")
        self.add_output("score",       "float")
        self.add_output("adjustments", "string")

    async def execute(self, inputs):
        plan_json = str(inputs.get("plan_json", "") or "")
        try:
            plan_dict = json.loads(plan_json) if plan_json.strip() else {}
        except Exception as exc:
            self.log_error(f"Failed to parse plan_json: {exc}")
            return {"result_json": "{}", "score": 0.0, "adjustments": "", "exec_out": True}
        try:
            engine = get_lighting_readability_engine()
            result = engine.evaluate_readability(plan_dict)
            adjustments = engine.recommend_adjustments(plan_dict)
            self.log_info(
                f"Readability score={result.score:.2f}. "
                f"Findings: {len(result.findings)}. Recommendations: {len(result.recommendations)}."
            )
            return {
                "result_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                "score":       result.score,
                "adjustments": json.dumps(adjustments, default=str),
                "exec_out":    True,
            }
        except Exception as exc:
            self.log_error(f"Readability evaluation failed: {exc}")
            return {"result_json": "{}", "score": 0.0, "adjustments": "", "exec_out": True}

def register_node():
    return Hou_Mcp_Lighting_Readability
